// shared/contentFactory.ts
function publicationBlockers(checks) {
  const blockers = [];
  if (!checks.sourcePackageApproved) blockers.push("The destination source package is not approved.");
  if (!checks.sourceReviewed) blockers.push("The factual source review is incomplete.");
  if (!checks.affiliateDisclosureReviewed) blockers.push("Affiliate disclosure review is incomplete.");
  if (!checks.visualRightsReviewed) blockers.push("Visual rights review is incomplete.");
  if (checks.requiresVisualAssetEvidence && !checks.visualAssetEvidenceComplete) blockers.push("The visual source, licence, attribution, rights evidence, or approved-use record is incomplete.");
  if (!checks.humanApproved) blockers.push("A human editor has not approved this asset.");
  return blockers;
}
function canPublishAsset(checks) {
  return publicationBlockers(checks).length === 0;
}

// server/routers/contentFactory.ts
var packageStatusSchema = external_exports.enum(["research", "review", "approved"]);
var assetStatusSchema = external_exports.enum(["draft", "review", "approved"]);
var assetTypeSchema = external_exports.enum(["guide_pdf", "product_page", "article", "pin", "short_video", "email", "creator_brief", "visual_asset"]);
var researchClaimCategorySchema = external_exports.enum(["anchor", "experience", "incident", "mobility", "access", "venue", "weather", "food", "safety", "other"]);
var researchClaimStatusSchema = external_exports.enum(["lead", "verified", "stale", "excluded"]);
var sourcePackageInputSchema = external_exports.object({ destination: external_exports.string().trim().min(2).max(120), title: external_exports.string().trim().min(3).max(180), status: packageStatusSchema.default("research"), notes: external_exports.string().trim().max(4e3).optional() });
var researchClaimInputSchema = external_exports.object({ sourcePackageId: external_exports.number().int().positive(), category: researchClaimCategorySchema.default("other"), claim: external_exports.string().trim().min(8).max(4e3), sourceTitle: external_exports.string().trim().min(3).max(180), sourceUrl: external_exports.string().trim().url().max(2048), evidenceNote: external_exports.string().trim().max(2e3).optional(), status: researchClaimStatusSchema.default("lead"), freshnessDays: external_exports.number().int().min(1).max(3650).default(30), lastVerifiedAt: external_exports.coerce.date().optional(), nextReviewAt: external_exports.coerce.date().optional(), reviewer: external_exports.string().trim().max(120).optional() });
var contentAssetInputSchema = external_exports.object({ sourcePackageId: external_exports.number().int().positive(), assetType: assetTypeSchema, title: external_exports.string().trim().min(3).max(180), sourceReviewed: external_exports.boolean().default(false), affiliateDisclosureReviewed: external_exports.boolean().default(false), visualRightsReviewed: external_exports.boolean().default(false), visualSourceUrl: external_exports.string().trim().url().max(2048).optional(), visualLicense: external_exports.string().trim().min(2).max(180).optional(), visualAttribution: external_exports.string().trim().min(2).max(320).optional(), visualRightsEvidenceUrl: external_exports.string().trim().url().max(2048).optional(), approvedUses: external_exports.string().trim().min(2).max(320).optional(), humanApproved: external_exports.boolean().default(false) }).superRefine((input, ctx) => {
  if (input.assetType !== "visual_asset") return;
  const requiredFields = ["visualSourceUrl", "visualLicense", "visualAttribution", "visualRightsEvidenceUrl", "approvedUses"];
  for (const field of requiredFields) if (!input[field]) ctx.addIssue({ code: "custom", path: [field], message: "Visual assets require documented source, licence, attribution, rights evidence, and approved uses." });
  if (input.visualRightsReviewed && requiredFields.some((field) => !input[field])) ctx.addIssue({ code: "custom", path: ["visualRightsReviewed"], message: "Visual rights cannot be marked reviewed until the licensing record is complete." });
});
var contentFactoryRouter = router({
  list: adminProcedure.query(() => listSourcePackagesWithAssets()),
  createPackage: adminProcedure.input(sourcePackageInputSchema).mutation(async ({ input }) => {
    await addSourcePackage(input);
    return { success: true };
  }),
  createAsset: adminProcedure.input(contentAssetInputSchema).mutation(async ({ input }) => {
    await addContentAsset(input);
    return { success: true };
  }),
  updatePackageStatus: adminProcedure.input(external_exports.object({ id: external_exports.number().int().positive(), status: packageStatusSchema })).mutation(async ({ input }) => {
    if (input.status === "approved") {
      const record2 = await getSourcePackageWithClaims(input.id);
      if (!record2) throw new TRPCError({ code: "NOT_FOUND", message: "Source package not found." });
      const readiness2 = evaluateResearchReadiness(record2.claims);
      if (!readiness2.canApprovePackage) throw new TRPCError({ code: "BAD_REQUEST", message: readiness2.blockers.join(" ") });
    }
    await setSourcePackageStatus(input.id, input.status);
    return { success: true };
  }),
  createClaim: adminProcedure.input(researchClaimInputSchema).mutation(async ({ input }) => {
    await addResearchClaim(input);
    return { success: true };
  }),
  updateClaimStatus: adminProcedure.input(external_exports.object({ id: external_exports.number().int().positive(), status: researchClaimStatusSchema, reviewer: external_exports.string().trim().max(120).optional() })).mutation(async ({ input }) => {
    await setResearchClaimStatus(input.id, input.status, input.reviewer);
    return { success: true };
  }),
  updateAssetStatus: adminProcedure.input(external_exports.object({ id: external_exports.number().int().positive(), status: assetStatusSchema })).mutation(async ({ input }) => {
    if (input.status === "approved") {
      const record2 = await getContentAssetWithPackage(input.id);
      if (!record2?.package) throw new TRPCError({ code: "NOT_FOUND", message: "Content asset or source package not found." });
      const packageRecord = await getSourcePackageWithClaims(record2.package.id);
      if (!packageRecord) throw new TRPCError({ code: "NOT_FOUND", message: "Source package not found." });
      const readiness2 = evaluateResearchReadiness(packageRecord.claims);
      if (record2.package.status !== "approved" || !readiness2.canApprovePackage) throw new TRPCError({ code: "BAD_REQUEST", message: "Approve the source package only after its current evidence gate passes." });
      const visualAssetEvidenceComplete = record2.asset.assetType !== "visual_asset" || Boolean(record2.asset.visualSourceUrl && record2.asset.visualLicense && record2.asset.visualAttribution && record2.asset.visualRightsEvidenceUrl && record2.asset.approvedUses);
      const checks = { sourcePackageApproved: true, sourceReviewed: record2.asset.sourceReviewed, affiliateDisclosureReviewed: record2.asset.affiliateDisclosureReviewed, visualRightsReviewed: record2.asset.visualRightsReviewed, humanApproved: record2.asset.humanApproved, requiresVisualAssetEvidence: record2.asset.assetType === "visual_asset", visualAssetEvidenceComplete };
      if (!canPublishAsset(checks)) throw new TRPCError({ code: "BAD_REQUEST", message: publicationBlockers(checks)[0] ?? "Complete the publication review gate before approval." });
    }
    await setContentAssetStatus(input.id, input.status);
    return { success: true };
  })
});

